// src/tools/unicode-picker/index.ts
var MAX_RESULTS = 100;
var LABELS2 = new Map(CATEGORIES.map((c) => [c.id, c.label]));
var HAYSTACK = new Map(
  ENTRIES.map((e) => [e, `${e.name} ${e.category} ${LABELS2.get(e.category) ?? ""}`.toLowerCase()])
);
function score(e, raw, q) {
  if (raw && e.char === raw) return 0;
  if (!q) return 3;
  if (e.name.startsWith(q)) return 1;
  if (e.name.includes(q)) return 2;
  return 3;
}
__name(score, "score");
function search(query, category) {
  const raw = (query ?? "").trim();
  const q = raw.toLowerCase();
  const terms = q.split(/\s+/).filter(Boolean);
  const pool = category === "all" ? ENTRIES : ENTRIES.filter((e) => e.category === category);
  const hits = pool.filter((e) => {
    if (!terms.length) return true;
    if (e.char === raw) return true;
    const hay = HAYSTACK.get(e);
    return terms.every((t) => hay.includes(t));
  });
  return hits.map((e, i) => ({ e, i, s: score(e, raw, q) })).sort((a, b2) => a.s - b2.s || a.i - b2.i).map((x2) => x2.e);
}
__name(search, "search");
function describe(e) {
  return `${e.name} \xB7 ${e.codepoint} \xB7 ${e.htmlEntity}`;
}
__name(describe, "describe");
function run22(input, opts) {
  const category = String(opts?.category ?? "all").trim() || "all";
  if (category !== "all" && !LABELS2.has(category))
    throw new ToolError(
      "unknown-category",
      `Unknown category "${category}".`,
      `Use "all" or one of: ${CATEGORIES.map((c) => c.id).join(", ")}.`
    );
  const query = (input ?? "").trim();
  const hits = search(query, category);
  if (!hits.length) {
    const where = category === "all" ? "any category" : `the ${LABELS2.get(category)} category`;
    return {
      "No matches": `Nothing in ${where} matches "${query}". Try a shorter query like "arrow", "dash", "greek" or "space", or paste the character itself.`
    };
  }
  const out = {};
  for (const e of hits.slice(0, MAX_RESULTS)) out[e.char] = describe(e);
  const extra = hits.length - MAX_RESULTS;
  if (extra > 0)
    out[`\u2026and ${extra} more`] = "Narrow the search or pick a category to see the rest of the matches.";
  return out;
}
__name(run22, "run");

